<?php $session_data=$session_data??['title'=>'','date'=>date('Y-m-d'),'session_type'=>'Erg','workout_format'=>'single_distance','coach_notes'=>'']; $segments=$segments??[]; ?>
<div class="form-row"><div class="form-group"><label class="form-label" for="title">Session title</label><input id="title" name="title" type="text" maxlength="255" required value="<?= htmlspecialchars($session_data['title']) ?>" placeholder="e.g. 4 × 1000m"></div><div class="form-group"><label class="form-label" for="date">Date</label><input id="date" name="date" type="date" required value="<?= htmlspecialchars($session_data['date']) ?>"></div></div>
<div class="form-row"><div class="form-group"><label class="form-label" for="session_type">Session type</label><select id="session_type" name="session_type"><option value="Erg" <?= $session_data['session_type']==='Erg'?'selected':'' ?>>Erg</option><option value="Water" <?= $session_data['session_type']==='Water'?'selected':'' ?>>Water</option></select></div><div class="form-group"><label class="form-label" for="status">Status</label><select id="status" name="status"><?php foreach(['upcoming'=>'Upcoming','open'=>'Open for Results','completed'=>'Completed'] as $v=>$label): ?><option value="<?= $v ?>" <?= ($session_data['status']??'upcoming')===$v?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div></div>
<div class="form-row"><div class="form-group"><label class="form-label" for="purpose">Workout purpose <span class="optional">Optional</span></label><select id="purpose" name="purpose"><option value="">Not specified</option><?php foreach(['UT2','UT1','AT','TR','Race/Test','Technique'] as $v): ?><option value="<?= $v ?>" <?= ($session_data['purpose']??'')===$v?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select></div><div class="form-group" id="boat-class-group"><label class="form-label" for="boat_class">Boat / class <span class="optional">Optional</span></label><select id="boat_class" name="boat_class"><option value="">Not specified</option><?php foreach(['8+','4+','4-','2-','2x','1x','Other'] as $v): ?><option value="<?= $v ?>" <?= ($session_data['boat_class']??'')===$v?'selected':'' ?>><?= $v ?></option><?php endforeach ?></select></div></div>
<section id="erg-builder"><div class="form-group"><label class="form-label" for="workout_format">Workout type</label><select id="workout_format" name="workout_format"><?php foreach(['single_distance'=>'Single Distance','single_time'=>'Single Time','distance_intervals'=>'Distance Intervals','time_intervals'=>'Time Intervals','variable'=>'Variable Workout'] as $v=>$label): ?><option value="<?= $v ?>" <?= $session_data['workout_format']===$v?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div><div id="erg-segments" class="builder-list"></div><button id="add-segment" type="button" class="btn btn-secondary">+ Add Segment</button></section>
<section id="water-builder"><div class="builder-heading"><div><p class="eyebrow">Water workout</p><h2>Sheds / pieces</h2></div><button id="add-shed" type="button" class="btn btn-secondary">+ Add Shed / Piece</button></div><div id="water-segments" class="builder-list"></div></section>
<div class="form-group"><label class="form-label" for="coach_notes">General coach notes <span class="optional">Optional</span></label><textarea id="coach_notes" name="coach_notes" maxlength="5000" placeholder="Notes that apply to the whole session..."><?= htmlspecialchars($session_data['coach_notes']) ?></textarea></div>
<script type="application/json" id="initial-segments"><?= json_encode($segments,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script>
<script>
(function(){var type=document.getElementById('session_type'),format=document.getElementById('workout_format'),erg=document.getElementById('erg-builder'),water=document.getElementById('water-builder'),boat=document.getElementById('boat-class-group'),ergList=document.getElementById('erg-segments'),waterList=document.getElementById('water-segments'),initial=JSON.parse(document.getElementById('initial-segments').textContent||'[]'),uid=0;
function esc(v){return String(v||'').replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})} function opt(value,label,current){return'<option value="'+value+'" '+(value===current?'selected':'')+'>'+label+'</option>'}
function card(s,isWater){var i=uid++, variable=format.value==='variable', title=isWater?'Shed / piece '+(waterList.children.length+1):variable?'Segment '+(ergList.children.length+1):'Workout details';var st=isWater?'water_shed':variable?(s.segment_type||'variable_distance'):({single_distance:'single_distance',single_time:'single_time',distance_intervals:'distance_interval',time_intervals:'time_interval'}[format.value]);var unit=st.indexOf('time')>=0?'minutes':'metres';return '<article class="segment-card"><div class="segment-card-head"><h3>'+title+'</h3><div class="segment-controls"><button type="button" class="icon-btn move-up" aria-label="Move up">↑</button><button type="button" class="icon-btn move-down" aria-label="Move down">↓</button><button type="button" class="btn btn-danger btn-small remove-segment">Remove</button></div></div><input type="hidden" data-field="segment_type" value="'+esc(st)+'">'+(isWater?'<div class="form-group"><label class="form-label">Description</label><input data-field="title" maxlength="255" value="'+esc(s.title)+'" placeholder="e.g. 30 hard / 10 light or Race starts"></div>':'')+(variable?'<div class="form-group"><label class="form-label">Segment type</label><select class="segment-kind" data-field="segment_type">'+opt('variable_distance','Distance',st)+opt('variable_time','Time',st)+'</select></div>':'')+'<div class="form-row">'+((isWater||st.indexOf('interval')>=0)?'<div class="form-group"><label class="form-label">Repetitions <span class="optional">Optional</span></label><input data-field="repetitions" type="number" min="1" max="999" value="'+esc(s.repetitions)+'"></div>':'')+'<div class="form-group"><label class="form-label">Work amount</label><input data-field="work_value" maxlength="100" value="'+esc(s.work_value)+'" placeholder="'+(isWater?'30 or Start + 20':'e.g. 1000')+'"></div><div class="form-group"><label class="form-label">Work unit</label><select data-field="work_unit">'+['metres','seconds','minutes','strokes'].map(function(u){return opt(u,u,s.work_unit||unit)}).join('')+'</select></div></div><div class="form-row"><div class="form-group"><label class="form-label">Recovery <span class="optional">Optional</span></label><input data-field="recovery_value" maxlength="100" value="'+esc(s.recovery_value)+'"></div><div class="form-group"><label class="form-label">Recovery unit</label><select data-field="recovery_unit"><option value="">—</option>'+['metres','seconds','minutes','strokes'].map(function(u){return opt(u,u,s.recovery_unit)}).join('')+'</select></div></div><div class="form-row"><div class="form-group"><label class="form-label">Target rate <span class="optional">Optional</span></label><input data-field="target_rate" maxlength="50" value="'+esc(s.target_rate)+'" placeholder="e.g. 28–30"></div>'+(!isWater?'<div class="form-group"><label class="form-label">Target split <span class="optional">Optional</span></label><input data-field="target_split" maxlength="50" value="'+esc(s.target_split)+'" placeholder="e.g. 2:05"></div>':'')+'</div><div class="form-group"><label class="form-label">Notes <span class="optional">Optional</span></label><textarea data-field="notes" maxlength="5000" placeholder="Coaching focus for this '+(isWater?'shed':'segment')+'...">'+esc(s.notes)+'</textarea></div></article>'}
function renumber(list){Array.from(list.children).forEach(function(c,n){c.querySelectorAll('[data-field]').forEach(function(el){el.name='segments['+n+']['+el.dataset.field+']'});var h=c.querySelector('h3');if(list===waterList)h.textContent='Shed / piece '+(n+1);else if(format.value==='variable')h.textContent='Segment '+(n+1)})}
function bind(list){renumber(list)} function add(list,s,isWater){list.insertAdjacentHTML('beforeend',card(s||{},isWater));bind(list)}
function rebuildErg(){ergList.innerHTML='';var variable=format.value==='variable', relevant=initial.filter(function(s){return s.segment_type!=='water_shed'});if(variable){(relevant.length?relevant:[{}]).forEach(function(s){add(ergList,s,false)})}else add(ergList,relevant[0]||{},false);document.getElementById('add-segment').hidden=!variable;initial=[]}
function toggle(){var isErg=type.value==='Erg';erg.hidden=!isErg;water.hidden=isErg;boat.hidden=isErg;if(isErg&&!ergList.children.length)rebuildErg();if(!isErg&&!waterList.children.length){var sheds=initial.filter(function(s){return s.segment_type==='water_shed'});(sheds.length?sheds:[{}]).forEach(function(s){add(waterList,s,true)});initial=[]}}
document.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;if(b.id==='add-segment')add(ergList,{},false);if(b.id==='add-shed')add(waterList,{},true);var c=b.closest('.segment-card');if(!c)return;var list=c.parentElement;if(b.classList.contains('remove-segment')&&list.children.length>1)c.remove();if(b.classList.contains('move-up')&&c.previousElementSibling)list.insertBefore(c,c.previousElementSibling);if(b.classList.contains('move-down')&&c.nextElementSibling)list.insertBefore(c.nextElementSibling,c);renumber(list)});type.addEventListener('change',toggle);format.addEventListener('change',function(){initial=[];rebuildErg()});toggle();
})();
</script>
